use super::*;
fn stopped()->Result<bool>{Ok(false)}
fn running()->Result<bool>{Ok(true)}
#[test]fn rejects_windows_escape_and_protected_paths(){for p in ["../outside","/absolute","a\\b","C:/game","file:stream","CON.txt","a/NUL","data/settings.json",".oo-client-update/x","OOLauncher.exe","MeowLauncher.exe","MeowManager.exe","MeowGM.exe","a/../b","a./x","a//b"]{assert!(safe_relative(p).is_err(),"{p}");}assert!(safe_relative("ImagePacks2/角色图像.NPK").is_ok());assert!(Source::new("sponsor","s4a21","a21","http://example.test/m.json","http://example.test/files/").is_err());}
#[test]fn production_trust_rejects_other_origin_and_normalization(){let s=Source::new("sponsor","test","generic","https://launcher.invalid/manifest.json","https://launcher.invalid/launcher/client/meowopia-custom/s4a21/releases/").unwrap();assert!(!s.trusted("https://share.feijipan.com/s/ccwmJYpq"));assert!(!s.trusted("https://launcher.invalid/launcher/client/meowopia-custom/s4a21/releases/../other.bin"));assert!(!s.trusted("https://launcher.invalid/launcher/client/meowopia-custom/s4a21/releases/%2e%2e/other.bin"));assert!(!s.trusted("https://launcher.invalid/launcher/client/meowopia-custom/s4a21/releases/file.bin?token=x"));}
#[tokio::test]
#[ignore="requires isolated real HTTP Range fixture"]
async fn http_range_workflow(){
 let origin=std::env::var("OO_DIST_FIXTURE").expect("fixture origin");assert!(origin.starts_with("http://127.0.0.1:"));
 let d=tempfile::tempdir().unwrap();let root=d.path().join("客户端 安装");
 let first=Engine::new(Source::fixture(&origin,"v1"));let plan=first.install(&root,stopped).await.unwrap();assert_eq!(plan.changed_files,5);assert_eq!(installed(&root).unwrap().unwrap().version,"1.0.0");
 let v1=installed(&root).unwrap().unwrap();for f in &v1.files{assert!(matches(&root.join(&f.path),f.size,&f.sha256));}
 fs::create_dir_all(root.join("data")).unwrap();fs::write(root.join("data/settings.json"),b"user settings preserved").unwrap();fs::write(root.join("OOLauncher.exe"),b"launcher preserved").unwrap();
 fs::write(root.join("GameGaurd.ini"),b"player plugin preferences").unwrap();
 let second=Engine::new(Source::fixture(&origin,"v2"));let plan=second.install(&root,stopped).await.unwrap();assert_eq!(plan.changed_files,2);assert_eq!(plan.preserved_settings,1);assert_eq!(fs::read(root.join("GameGaurd.ini")).unwrap(),b"player plugin preferences");assert_eq!(plan.installed_version.as_deref(),Some("1.0.0"));assert!(!root.join("SoundPacks/main.ogg").exists());assert!(root.join("SoundPacks/new.ogg").exists());assert_eq!(fs::read(root.join("data/settings.json")).unwrap(),b"user settings preserved");assert_eq!(fs::read(root.join("OOLauncher.exe")).unwrap(),b"launcher preserved");
 second.install(&root,stopped).await.unwrap();
 let v2=installed(&root).unwrap().unwrap();for f in &v2.files{if !setting(&f.path){assert!(matches(&root.join(&f.path),f.size,&f.sha256));}}assert_eq!(second.check(&root).await.unwrap().changed_files,0);
 let early_stats:serde_json::Value=reqwest::Client::new().get(format!("{origin}/stats")).send().await.unwrap().json().await.unwrap();assert_eq!(early_stats["requests"]["/files/v1/dnf.bin"].as_u64().unwrap_or(0),0);assert_eq!(early_stats["requests"]["/files/v1/images.bin"].as_u64().unwrap_or(0),0);
 let latest=d.path().join("latest-first");second.install(&latest,stopped).await.unwrap();assert!(latest.join("DNF.exe").exists());
 let conflict=d.path().join("conflict");first.install(&conflict,stopped).await.unwrap();fs::write(conflict.join("SoundPacks/main.ogg"),b"player modified this managed file").unwrap();assert_eq!(second.install(&conflict,stopped).await.err().unwrap().code,"client_remove_modified");assert_eq!(installed(&conflict).unwrap().unwrap().version,"1.0.0");

 for name in ["bad-hash","bad-zip-path","bad-zip-link","bad-zip-content","bad-edition","bad-size"] {
  let r=d.path().join(name);let bad=Engine::new(Source::fixture(&origin,name));assert!(bad.install(&r,stopped).await.is_err(),"{name}");assert!(!r.join("DNF.exe").exists(),"{name}");assert!(!d.path().join("outside.bin").exists());
 }
 let wrapped=d.path().join("wrapped");Engine::new(Source::fixture(&origin,"wrapped")).install(&wrapped,stopped).await.unwrap();assert!(wrapped.join("DNF.exe").is_file());assert!(!wrapped.join("S4A21_CN").exists());
 let paused=d.path().join("resume");let engine=Engine::new(Source::fixture(&origin,"resume"));let e=engine.install(&paused,stopped).await.err().unwrap();assert_eq!(e.code,"client_download_interrupted");assert!(!paused.join("DNF.exe").exists());assert!(engine.install(&paused,stopped).await.is_ok());
 let pause_root=d.path().join("pause");let pausable=std::sync::Arc::new(Engine::new(Source::fixture(&origin,"pause")));let cancel=pausable.clone();let cancellation=tokio::spawn(async move{while cancel.progress().received<65536{tokio::time::sleep(Duration::from_millis(5)).await;}cancel.cancel();});assert_eq!(pausable.install(&pause_root,stopped).await.err().unwrap().code,"client_update_cancelled");cancellation.await.unwrap();assert!(!pause_root.join("DNF.exe").exists());pausable.install(&pause_root,stopped).await.unwrap();
 let blocked=d.path().join("running");assert_eq!(first.install(&blocked,running).await.err().unwrap().code,"game_running");assert!(!blocked.exists());
 let rollback_root=d.path().join("rollback");first.install(&rollback_root,stopped).await.unwrap();let before=fs::read(rollback_root.join("Script.pvf")).unwrap();let failure=Engine::new(Source::fixture(&origin,"v2"));failure.fail_after.store(1,Ordering::SeqCst);assert!(failure.install(&rollback_root,stopped).await.is_err());assert_eq!(fs::read(rollback_root.join("Script.pvf")).unwrap(),before);assert!(!rollback_root.join("SoundPacks/new.ogg").exists());assert!(rollback_root.join("SoundPacks/main.ogg").exists());assert_eq!(installed(&rollback_root).unwrap().unwrap().version,"1.0.0");failure.fail_after.store(0,Ordering::SeqCst);failure.install(&rollback_root,stopped).await.unwrap();
 // Simulate a killed process between old-file backup and durable commit.
 let crash_root=d.path().join("crash");first.install(&crash_root,stopped).await.unwrap();let old_script=fs::read(crash_root.join("Script.pvf")).unwrap();let tx=crash_root.join(WORK).join("c".repeat(64));fs::create_dir_all(tx.join("staged")).unwrap();let new=b"verified new fixture resource";fs::write(tx.join("staged/Script.pvf"),new).unwrap();let entry=Entry{path:"Script.pvf".into(),size:new.len() as u64,sha256:format!("{:x}",Sha256::digest(new)),url:None};let mut journal=prepare(&crash_root,&tx,&[entry],&[],&first.source).unwrap();journal.status="committing".into();json(&tx.join("journal.json"),&journal).unwrap();fs::create_dir_all(tx.join(&journal.backup_dir)).unwrap();fs::rename(crash_root.join("Script.pvf"),tx.join(&journal.backup_dir).join("Script.pvf")).unwrap();fs::rename(tx.join("staged/Script.pvf"),crash_root.join("Script.pvf")).unwrap();let unavailable=Engine::new(Source::fixture(&origin,"bad-edition"));assert!(unavailable.install(&crash_root,stopped).await.is_err());assert_eq!(fs::read(crash_root.join("Script.pvf")).unwrap(),old_script);assert_eq!(installed(&crash_root).unwrap().unwrap().version,"1.0.0");
 let stats:serde_json::Value=reqwest::Client::new().get(format!("{origin}/stats")).send().await.unwrap().json().await.unwrap();assert!(stats["rangeRequests"].as_u64().unwrap()>0);assert!(stats["requests"]["/files/v1/dnf.bin"].as_u64().unwrap_or(0)>0);assert_eq!(stats["requests"]["/files/v2/images.bin"].as_u64().unwrap_or(0),0);
 println!("verified: real HTTP first ZIP installation, raw incremental update, managed removal, unchanged files skipped, interruption with Range resume, checksum/size/unsafe ZIP/link/edition rejection, game-running guard, partial commit rollback, crash recovery and private settings preservation");
}
